class Solution:
    def hardestWorker(self, n: int, logs: List[List[int]]) -> int:
        prev, best, ans = 0, -1, -1
        for idx, t in logs:
            d = t - prev
            prev = t
            if d > best:
                best, ans = d, idx
        return ans

