class Solution {
public:
    int hardestWorker(int n, vector<vector<int>>& logs) {
        int prev = 0, best = -1, ans = -1;
        for (auto& log : logs) {
            int d = log[1] - prev;
            prev = log[1];
            if (d > best) {
                best = d;
                ans = log[0];
            }
        }
        return ans;
    }
};

