class Solution:
    def hardestWorker(self, n: int, logs: List[List[int]]) -> int:
        durs = [logs[0][1]]
        for i in range(1, len(logs)):
            durs.append(logs[i][1] - logs[i - 1][1])
        return logs[durs.index(max(durs))][0]

