class Solution {
public:
    int hardestWorker(int n, vector<vector<int>>& logs) {
        vector<int> durs;
        durs.push_back(logs[0][1]);
        for (int i = 1; i < (int)logs.size(); i++)
            durs.push_back(logs[i][1] - logs[i - 1][1]);
        int bi = 0;
        for (int i = 1; i < (int)durs.size(); i++)
            if (durs[i] > durs[bi]) bi = i;
        return logs[bi][0];
    }
};

