        int[] durs = new int[m];
        durs[0] = logs[0][1];
        for (int i = 1; i < m; i++) durs[i] = logs[i][1] - logs[i - 1][1];
        int bi = 0;
        for (int i = 1; i < m; i++) if (durs[i] > durs[bi]) bi = i;
        return logs[bi][0];
    }
}

